 <section className="panel-section"><div className="section-heading"><h2>基本操作</h2><MousePointer2 size={12} color="#a9b09e"/></div><div className="mode-switch"><button title={experimentalKeys?'選択 — Alt + V（試用）':'選択 — Alt + Vは候補・未検証のため無効'} className={mode==='select'?'selected':''} onClick={()=>{setMode('select');setObjectTool('dialogue');setSelectedPanel(null);}}><MousePointer2 size={16}/>選択</button><button title={experimentalKeys?'画面移動 — Alt + H（試用）':'画面移動 — Alt + Hは候補・未検証のため無効'} className={mode==='pan'?'selected':''} onClick={()=>setMode('pan')}><Hand size={16}/>画面移動</button></div><h2 className="subheading">吹き出しを追加</h2><div className="shape-buttons"><button title={experimentalKeys?'楕円 — Alt + Q（試用）':'楕円 — Alt + Qは候補・未検証のため無効'} onClick={()=>add('ellipse')} disabled={!!busy}><svg viewBox="0 0 80 60" aria-hidden="true"><path d="M40 7C59 7 72 16 72 29S60 49 43 49L30 57 31 48C16 46 8 39 8 29S21 7 40 7Z"/></svg><span>楕円</span><span className="shape-plus">＋</span></button><button title={experimentalKeys?'Alt + R（試用）':'Alt + Rは候補・未検証のため無効'} onClick={()=>add('rounded')} disabled={!!busy}><svg viewBox="0 0 80 60" aria-hidden="true"><rect x="9" y="9" width="62" height="41" rx="9"/></svg><span>角丸四角</span><span className="shape-plus">＋</span></button><button title={experimentalKeys?'Alt + T（試用）':'Alt + Tは候補・未検証のため無効'} onClick={()=>add('text')} disabled={!!busy}><Type size={38} aria-hidden="true"/><span>文字のみ</span><span className="shape-plus">＋</span></button><button title={experimentalKeys?'Alt + G（試用）':'Alt + Gは候補・未検証のため無効'} onClick={()=>add('zigzag')} disabled={!!busy}><svg viewBox="0 0 80 60" aria-hidden="true"><path d="m40 4 7 10 15-5-1 13 15 8-14 7 3 14-17-4-8 11-9-11-16 5 3-15L4 30l14-7-2-14 16 5Z"/></svg><span>ギザギザ</span><span className="shape-plus">＋</span></button></div></section>
