 <aside className={`right-panel ${panel==='properties'?'mobile-open':''}`}><div className="properties-heading"><div><p className="eyebrow">PROPERTIES</p><h2>プロパティ{b&&<span className="selected-panel-label" aria-label="選択中のオブジェクト">{b.kind==='text'?'文字のみ':b.kind==='ellipse'?'楕円':b.kind==='rounded'?'角丸四角':'ギザギザ'}</span>}{focusedFrame&&<span className="selected-panel-label" aria-label="選択中のコマ" aria-live="polite" data-panel-id={focusedFrame.id}>{focusedFrame.kind==='background'?'背景コマ':'コマ'} {focusedFrame.order+1}</span>}</h2></div><span className="properties-mark"><Type size={18}/></span><button className="mobile-close" aria-label="プロパティを閉じる" onClick={()=>setPanel(null)}><X size={18}/></button></div>
 {selectedFrame&&<PanelProperties details={panelDetails} operations={<><PanelOperations details={panelDetails} key={selectedFrame.id} panel={selectedFrame} project={doc.project} vertexEditing={vertexEditing} setVertexEditing={setVertexEditing} setImageEditing={setPanelImageEditing} update={patch=>apply({...ref.current.project,panels:ref.current.project.panels!.map(p=>p.id===selectedFrame.id?{...p,...patch}:p)})} split={splitFocused} beginMerge={beginMerge} mergeMode={mergeMode} cancelMerge={()=>setMergeMode(false)}/><PanelMembers project={doc.project} id={selectedFrame.id} select={selectBalloon}/></>} imageEditing={panelImageEditing} setImageEditing={v=>{setPanelImageEditing(v);setVertexEditing(false);}} loadImage={()=>panelImageInput.current?.click()} busy={!!busy} panel={selectedFrame} page={doc.project} updateBounds={patch=>{const p=ref.current.project,f=p.panels!.find(f=>f.id===selectedFrame.id)!;apply(editLinkedPanel(p,f.id,setPanelBounds(p,f,patch),patch.width!==undefined||patch.height!==undefined?'resize':'move'));}} update={patch=>apply({...doc.project,panels:doc.project.panels!.map(f=>f.id===selectedFrame.id?{...f,...patch}:f)})} remove={remove}/>}<div className="dialogue-properties" hidden={!!selectedFrame}><PropertiesPanel extra={b&&<BalloonMembership project={doc.project} b={b} update={patch=>{update(patch);if(patch.panelId!==undefined)setFocusedPanel(patch.panelId);}} copy={copyDialogue} paste={pasteDialogue} canPaste={!!clipboard}/>} clipEditing={clipEditing} setClipEditing={setClipEditing} b={b} textInfo={textInfo} textEditing={textEditing} editTarget={b?.kind==='text'?'text':editTarget} setEditTarget={setEditTarget} setTextFocused={setTextFocused} onTextFocus={()=>{setTextFocused(true);textSnapshot.current=structuredClone(ref.current.project);}} onTextBlur={()=>{setTextFocused(false);if(textSnapshot.current&&signature(textSnapshot.current)!==signature(ref.current.project))pushHistory(textSnapshot.current);textSnapshot.current=null;}} update={update} style={style} outline={outline} shadow={shadow} loadFamily={loadFamily} duplicate={duplicate} remove={remove}/></div>

 <div className="properties-footer"><span>非破壊編集</span><span>元の画像を保護</span></div></aside>
